INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-foundation-x23','official-vi-foundation','error_correction','Chọn cách giao tiếp phù hợp hơn trong tình huống cần làm rõ thông tin.','["Bạn có thể xác nhận lại thời gian và yêu cầu giúp tôi không?","Tôi đoán là vậy nên làm luôn.","Không cần nói gì.","Sai thì tính sau."]','["Bạn có thể xác nhận lại thời gian và yêu cầu giúp tôi không?"]','[]','Câu hỏi làm rõ trực tiếp và lịch sự giúp tránh hiểu nhầm.','','','','','','',0,1,'','',4,'["error-correction","pragmatics","professional"]',22,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-foundation-x24','official-vi-foundation','multiple_choice','Khi áp dụng nội dung của “Tiếng Việt — Foundation & Everyday” vào thực tế, mục tiêu quan trọng nhất là gì?','["Hiểu ý, dùng đúng ngữ cảnh và phản hồi phù hợp","Chỉ ghi nhớ đáp án của một lần chơi","Trả lời càng nhanh càng tốt dù chưa hiểu","Bỏ qua phần giải thích"]','["Hiểu ý, dùng đúng ngữ cảnh và phản hồi phù hợp"]','[]','Sky First Games ưu tiên khả năng sử dụng ngôn ngữ trong tình huống thực tế, không chỉ ghi nhớ đáp án.','','','','','','',0,1,'','',4,'["mastery","real-life","reflection"]',23,'2026-09-11','2026-09-11');
UPDATE question_sets SET description='Bộ bài nền tảng Tiếng Việt: từ vựng, hội thoại, dịch và xử lý tình huống. Bộ nâng cao gồm 24 câu đa dạng, có nghe, đọc, viết, tình huống và kiểm tra năng lực thực tế.', updated_at='2026-09-11', version=version+1 WHERE id='official-vi-foundation';

INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-professional-x09','official-vi-professional','fill_blank','Hoàn thành ý phù hợp trong ngữ cảnh School & Professional: “Thông báo về lịch hoặc nhiệm vụ” tương ứng với ___.','["Thông báo về lịch hoặc nhiệm vụ","Một câu chuyện cổ tích","Mô tả thời tiết","Quảng cáo trò chơi"]','["Thông báo về lịch hoặc nhiệm vụ"]','[]','Trong bộ bài Tiếng Việt, “Thông báo về lịch hoặc nhiệm vụ” được dùng với nghĩa/ý phù hợp là “Thông báo về lịch hoặc nhiệm vụ”.','Dựa vào ngữ cảnh của cụm từ.','','','','','',0,1,'','',2,'["reinforcement","fill-blank","school-&-professional"]',8,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-professional-x10','official-vi-professional','multiple_select','Chọn HAI hành động phù hợp khi giao tiếp trong bối cảnh School & Professional.','["Xác nhận lại thông tin quan trọng","Phản hồi rõ ràng và lịch sự","Bỏ qua yêu cầu mà không trả lời","Đoán thông tin còn thiếu rồi làm ngay"]','["Xác nhận lại thông tin quan trọng","Phản hồi rõ ràng và lịch sự"]','[]','Giao tiếp hiệu quả cần xác nhận thông tin và phản hồi rõ ràng.','','','','','','',0,1,'','',3,'["scenario","multiple-select","communication"]',9,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-professional-x11','official-vi-professional','reading_group','Ý chính của đoạn đọc là gì?','["Xác nhận thông tin trước khi hành động","Không cần kiểm tra thông tin","Nên tránh giao tiếp","Chỉ cần hoàn thành thật nhanh"]','["Xác nhận thông tin trước khi hành động"]','[]','Đoạn đọc nhấn mạnh việc kiểm tra và xác nhận thông tin trước khi thực hiện.','','','','','','',0,1,'Trong tình huống School & Professional, người học nhận một yêu cầu liên quan đến Workplace & Real Life. Trước khi bắt đầu, người đó kiểm tra lại thời gian, địa điểm và mục tiêu, sau đó mới phản hồi và thực hiện nhiệm vụ.','',3,'["reading","inference","real-life"]',10,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-professional-x12','official-vi-professional','scenario_decision','Bạn đang ở tình huống School & Professional và nhận thông tin chưa đầy đủ. Cách xử lý tốt nhất là gì?','["Hỏi lại phần còn thiếu rồi xác nhận trước khi thực hiện","Tự đoán toàn bộ thông tin","Không phản hồi","Chờ người khác giải quyết"]','["Hỏi lại phần còn thiếu rồi xác nhận trước khi thực hiện"]','[]','Xác nhận thông tin giúp giảm sai sót trong tình huống thực tế.','','','','','','',0,1,'','',3,'["scenario","decision","real-life"]',11,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-professional-x13','official-vi-professional','roleplay','Role-play School & Professional: chọn phản hồi thể hiện bạn đã hiểu nhiệm vụ và sẽ xử lý đúng cách.','["Tôi đã nhận thông tin. Tôi sẽ kiểm tra lại chi tiết và phản hồi nếu có điểm chưa rõ.","Ừ, để đó.","Không biết.","Tôi sẽ tự đoán phần còn thiếu."]','["Tôi đã nhận thông tin. Tôi sẽ kiểm tra lại chi tiết và phản hồi nếu có điểm chưa rõ."]','[]','Phản hồi chuyên nghiệp nên xác nhận đã nhận và nêu bước tiếp theo.','','','','','','',0,1,'','',4,'["roleplay","professional","communication"]',12,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-professional-x14','official-vi-professional','transformation','Viết lại câu yêu cầu theo hướng lịch sự, rõ ràng và phù hợp hơn.','[]','["Vui lòng xác nhận thông tin và cho tôi biết nếu có thay đổi.","Xin vui lòng xác nhận thông tin và thông báo cho tôi nếu có thay đổi."]','[]','Một yêu cầu tốt nên có hành động rõ ràng và giọng điệu lịch sự.','','','','','','',0,1,'','',4,'["writing","register","transformation"]',13,'2026-09-11','2026-09-11');
