UPDATE question_sets SET description='Bộ nâng cao nhiều dạng bài, tập trung năng lực thực tế và tư duy xử lý tình huống. Bộ nâng cao gồm 24 câu đa dạng, có nghe, đọc, viết, tình huống và kiểm tra năng lực thực tế.', updated_at='2026-09-11', version=version+1 WHERE id='official-vi-extra-34';

INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-extra-35-x09','official-vi-extra-35','fill_blank','Hoàn thành ý phù hợp trong ngữ cảnh School Workplace: “vui lòng xác nhận trước khi triển khai” tương ứng với ___.','["Cung cấp thông tin tổ chức hoạt động","Kể chuyện giải trí","Quảng cáo sản phẩm","Xin nghỉ học"]','["Cung cấp thông tin tổ chức hoạt động"]','[]','Trong bộ bài Tiếng Việt, “vui lòng xác nhận trước khi triển khai” được dùng với nghĩa/ý phù hợp là “Cung cấp thông tin tổ chức hoạt động”.','Dựa vào ngữ cảnh của cụm từ.','','','','','',0,1,'','',2,'["reinforcement","fill-blank","school-workplace"]',8,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-extra-35-x10','official-vi-extra-35','multiple_select','Chọn HAI hành động phù hợp khi giao tiếp trong bối cảnh School Workplace.','["Xác nhận lại thông tin quan trọng","Phản hồi rõ ràng và lịch sự","Bỏ qua yêu cầu mà không trả lời","Đoán thông tin còn thiếu rồi làm ngay"]','["Xác nhận lại thông tin quan trọng","Phản hồi rõ ràng và lịch sự"]','[]','Giao tiếp hiệu quả cần xác nhận thông tin và phản hồi rõ ràng.','','','','','','',0,1,'','',3,'["scenario","multiple-select","communication"]',9,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-extra-35-x11','official-vi-extra-35','reading_group','Ý chính của đoạn đọc là gì?','["Xác nhận thông tin trước khi hành động","Không cần kiểm tra thông tin","Nên tránh giao tiếp","Chỉ cần hoàn thành thật nhanh"]','["Xác nhận thông tin trước khi hành động"]','[]','Đoạn đọc nhấn mạnh việc kiểm tra và xác nhận thông tin trước khi thực hiện.','','','','','','',0,1,'Trong tình huống School Workplace, người học nhận một yêu cầu liên quan đến School Workplace. Trước khi bắt đầu, người đó kiểm tra lại thời gian, địa điểm và mục tiêu, sau đó mới phản hồi và thực hiện nhiệm vụ.','',3,'["reading","inference","real-life"]',10,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-extra-35-x12','official-vi-extra-35','scenario_decision','Bạn đang ở tình huống School Workplace và nhận thông tin chưa đầy đủ. Cách xử lý tốt nhất là gì?','["Hỏi lại phần còn thiếu rồi xác nhận trước khi thực hiện","Tự đoán toàn bộ thông tin","Không phản hồi","Chờ người khác giải quyết"]','["Hỏi lại phần còn thiếu rồi xác nhận trước khi thực hiện"]','[]','Xác nhận thông tin giúp giảm sai sót trong tình huống thực tế.','','','','','','',0,1,'','',3,'["scenario","decision","real-life"]',11,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-extra-35-x13','official-vi-extra-35','roleplay','Role-play School Workplace: chọn phản hồi thể hiện bạn đã hiểu nhiệm vụ và sẽ xử lý đúng cách.','["Tôi đã nhận thông tin. Tôi sẽ kiểm tra lại chi tiết và phản hồi nếu có điểm chưa rõ.","Ừ, để đó.","Không biết.","Tôi sẽ tự đoán phần còn thiếu."]','["Tôi đã nhận thông tin. Tôi sẽ kiểm tra lại chi tiết và phản hồi nếu có điểm chưa rõ."]','[]','Phản hồi chuyên nghiệp nên xác nhận đã nhận và nêu bước tiếp theo.','','','','','','',0,1,'','',4,'["roleplay","professional","communication"]',12,'2026-09-11','2026-09-11');
