INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('pt-school-scenario-x09','official-pt-school-scenario','fill_blank','Hoàn thành ý phù hợp trong ngữ cảnh School Workplace: “Por favor, confirme a sala.” tương ứng với ___.','["Pode repetir, por favor?","Không cần nói gì.","Nói thật to một từ bất kỳ.","Rời cuộc trò chuyện."]','["Pode repetir, por favor?"]','[]','Trong bộ bài Português, “Por favor, confirme a sala.” được dùng với nghĩa/ý phù hợp là “Pode repetir, por favor?”.','Dựa vào ngữ cảnh của cụm từ.','','','','','',0,1,'','',2,'["reinforcement","fill-blank","school-workplace"]',8,'2026-09-11','2026-09-11');
