UPDATE question_sets SET description='Bài tập thực tế ở trường: đổi lịch, đổi phòng, thông báo, phối hợp và xử lý tình huống lớp học. Bộ nâng cao gồm 24 câu đa dạng, có nghe, đọc, viết, tình huống và kiểm tra năng lực thực tế.', updated_at='2026-09-11', version=version+1 WHERE id='official-pt-school-scenario';

INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('pt-travel-public-x09','official-pt-travel-public','fill_blank','Hoàn thành ý phù hợp trong ngữ cảnh Travel: “Onde fica a estação mais próxima?” tương ứng với ___.','["Onde fica a estação mais próxima?","Gostaria de fazer uma reserva.","Por favor, confirme a sala.","Pode repetir, por favor?"]','["Onde fica a estação mais próxima?"]','[]','Trong bộ bài Português, “Onde fica a estação mais próxima?” được dùng với nghĩa/ý phù hợp là “Onde fica a estação mais próxima?”.','Dựa vào ngữ cảnh của cụm từ.','','','','','',0,1,'','',2,'["reinforcement","fill-blank","travel"]',8,'2026-09-11','2026-09-11');
